using CommerceRunTimeDataModel = Microsoft.Dynamics.Commerce.Runtime.DataModel;
using CrtSalesTransaction = Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesTransaction;
using System.Collections.Generic;
using System.Reflection;

[ExtensionOf(classStr(RetailPricingEngineHelper))]
public final class RetailPricingEngineHelperGlobalUnifiedPricing_Extension
{
}

Method.Source:
public static Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesLine getCrtRetailSalesLine(
    SalesPurchLine _salesLine,
    RetailSalesPurchLineMap _retailSalesLine,
    SalesUnit _defaultSalesUnit,
    SalesPurchTable _salesTable)
{
    Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesLine crtSalesLine = next getCrtRetailSalesLine(_salesLine, _retailSalesLine, _defaultSalesUnit, _salesTable);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        SalesPurchLineInterface salesPurchLineInterface = _salesLine.salesPurchLineInterface();
        crtSalesLine.InventoryDimensionId = salesPurchLineInterface.parmInventDimId();
        crtSalesLine.SalesDate = System.DateTimeOffset::UtcNow;
    }

    return crtSalesLine;
}
